import{_ as d,o as t,c as o,a3 as c}from"./chunks/framework.B02wg2PO.js";const p=JSON.parse('{"title":"Data Model & Storage","description":"","frontmatter":{},"headers":[],"relativePath":"reference/data-model.md","filePath":"reference/data-model.md"}'),r={name:"reference/data-model.md"};function a(n,e,i,s,l,h){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="data-model-storage" tabindex="-1">Data Model &amp; Storage <a class="header-anchor" href="#data-model-storage" aria-label="Permalink to &quot;Data Model &amp; Storage&quot;">​</a></h1><p>Saidi keeps structured records in MongoDB and artifacts on disk. The split is deliberate: durable structured data lives in Mongo, while human-editable markdown memory and the scanned project registry stay as files because they are meant to be inspected and edited. Binary run output (images, deliverables, git worktrees) never enters the database.</p><h2 id="storage-engine" tabindex="-1">Storage engine <a class="header-anchor" href="#storage-engine" aria-label="Permalink to &quot;Storage engine&quot;">​</a></h2><p>MongoDB, accessed through Mongoose (<code>mongoose@^9</code>). There is no file-backed fallback: <code>connectMongo()</code> returns <code>false</code> on failure and the orchestrator treats that as fatal.</p><p>Mongo is the source of truth for every store. The connection is managed by the platform; nothing about it is configurable from a workspace.</p><table tabindex="0"><thead><tr><th>Behaviour</th><th>Value</th></tr></thead><tbody><tr><td>Server selection timeout</td><td>2500 ms on connect, 1500 ms for the <code>pingMongo</code> probe</td></tr><tr><td>Mongoose flags</td><td><code>strictQuery: true</code>, <code>bufferCommands: false</code></td></tr><tr><td>On <code>disconnected</code></td><td>Logs and exits after a 1 s grace window, so every in-memory working set is rebuilt from the DB on restart</td></tr></tbody></table><p>Every collection below is scoped by <code>orgId</code>. A query that could span workspaces is a bug, not a feature — see <a href="/docs/concepts/tenancy-and-identity">Tenancy, Identity &amp; Access</a>.</p><h3 id="external-edits" tabindex="-1">External edits <a class="header-anchor" href="#external-edits" aria-label="Permalink to &quot;External edits&quot;">​</a></h3><p>Saidi opens a MongoDB change stream filtered to <code>delete</code>/<code>drop</code>/<code>dropDatabase</code>/<code>invalidate</code> on the runs and activity collections only — the application itself never deletes those, so any such event is an external edit (mongosh, Compass, a restored dump). Events are debounced 250 ms, then the affected store is resynced for every loaded org and clients are told to re-pull. Change streams require a replica set; on a standalone <code>mongod</code> the watcher disables itself with a warning and external edits only appear after a restart.</p><h2 id="collections" tabindex="-1">Collections <a class="header-anchor" href="#collections" aria-label="Permalink to &quot;Collections&quot;">​</a></h2><p>Nineteen models define these schemas. Every one uses <code>versionKey: false</code> and <code>minimize: false</code>. Records that own a globally unique string id store it as <code>_id</code> (runs, crons, reflexes, playbooks, users, orgs); records whose id is only unique within an org use a compound <code>_id</code> (<code>&lt;orgId&gt;::&lt;id&gt;</code> for chats and agent definitions, <code>&lt;orgId&gt;:&lt;rel&gt;</code> for memory); platform-global blobs live under a fixed id.</p><h3 id="run" tabindex="-1"><code>Run</code> <a class="header-anchor" href="#run" aria-label="Permalink to &quot;`Run`&quot;">​</a></h3><p>The TypeScript <code>Run</code> interface is the shape of record; the schema stores the nested arrays as <code>Mixed</code> so it cannot drift. Full field semantics live in <a href="/docs/reference/run-object">The Run Object</a> — the table below is what the schema itself declares.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>_id</code></td><td><code>String</code> (required)</td><td>The run&#39;s own id</td></tr><tr><td><code>orgId</code></td><td><code>String</code> (indexed)</td><td>Owning org; absent on legacy local records</td></tr><tr><td><code>createdBy</code> / <code>createdByName</code> / <code>createdByEmail</code></td><td><code>String</code></td><td>The member who started it, plus their display identity</td></tr><tr><td><code>sharedWith</code></td><td><code>[String]</code></td><td>Members invited to view (cloud)</td></tr><tr><td><code>title</code></td><td><code>String</code> (required)</td><td>Short human title</td></tr><tr><td><code>brief</code></td><td><code>String</code> (default <code>&#39;&#39;</code>)</td><td>The original brief</td></tr><tr><td><code>status</code></td><td><code>String</code> (required, indexed)</td><td>Lifecycle state</td></tr><tr><td><code>createdAt</code></td><td><code>Number</code> (required)</td><td>Epoch ms</td></tr><tr><td><code>updatedAt</code></td><td><code>Number</code> (required, indexed)</td><td>Epoch ms; drives the bounded resync ordering</td></tr><tr><td><code>project</code> / <code>branch</code></td><td><code>String</code></td><td>Primary project and working branch</td></tr><tr><td><code>effortMode</code> / <code>providerProfile</code> / <code>model</code></td><td><code>String</code></td><td>Run-wide execution overrides</td></tr><tr><td><code>agentConfigs</code></td><td><code>Mixed</code></td><td>Per-actor overrides</td></tr><tr><td><code>primeSessionId</code></td><td><code>String</code></td><td>PRIME&#39;s session for this run</td></tr><tr><td><code>participants</code></td><td><code>[Mixed]</code> (default <code>[]</code>)</td><td>Every agent that took part</td></tr><tr><td><code>pendingApproval</code> / <code>attention</code></td><td><code>Mixed</code></td><td>Approval gate, latest attention transition</td></tr><tr><td><code>checklist</code> / <code>originalChecklist</code></td><td><code>[Mixed]</code></td><td>Live plan and the plan as first frozen</td></tr><tr><td><code>planVersion</code></td><td><code>Number</code></td><td>Plan amendment policy marker</td></tr><tr><td><code>planApproval</code></td><td><code>Mixed</code></td><td>Operator sign-off on the plan</td></tr><tr><td><code>playbookId</code></td><td><code>String</code></td><td>Set when the plan was replayed from a playbook</td></tr><tr><td><code>executionMode</code></td><td><code>String</code></td><td><code>guided</code> or <code>autonomous</code></td></tr><tr><td><code>optimizationMode</code> / <code>optimizationVersion</code></td><td><code>String</code></td><td>Rollout state stamped at creation</td></tr><tr><td><code>appliedMemories</code></td><td><code>[Mixed]</code></td><td>Memory selected before planning</td></tr><tr><td><code>version</code></td><td><code>String</code></td><td>Orchestrator build that started the run; stamped once</td></tr><tr><td><code>inFlight</code> / <code>inFlights</code></td><td><code>Mixed</code> / <code>[Mixed]</code></td><td>Legacy single flight, and every executing delegation</td></tr><tr><td><code>thread</code></td><td><code>[Mixed]</code> (default <code>[]</code>)</td><td>The ordered shared conversation</td></tr><tr><td><code>usageLog</code></td><td><code>[Mixed]</code></td><td>One entry per settled LLM call</td></tr><tr><td><code>verificationLog</code></td><td><code>[Mixed]</code></td><td>Append-only gate verdicts, kept on the run so an amendment cannot drop history</td></tr><tr><td><code>optimizationReport</code></td><td><code>Mixed</code></td><td>Retry counts, failure kinds, cost, max context</td></tr><tr><td><code>lastResult</code> / <code>lastActivity</code></td><td><code>String</code></td><td>Latest committed summary and live status line</td></tr></tbody></table><h3 id="activityevent" tabindex="-1"><code>ActivityEvent</code> <a class="header-anchor" href="#activityevent" aria-label="Permalink to &quot;`ActivityEvent`&quot;">​</a></h3><p>Append-only stream of operator directives, PRIME replies, tool steps and agent results.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>String</code> (indexed)</td><td>The event&#39;s own id</td></tr><tr><td><code>t</code></td><td><code>Number</code> (required, indexed)</td><td>Epoch ms</td></tr><tr><td><code>orgId</code></td><td><code>String</code> (indexed)</td><td>Owning org; absent on legacy local rows</td></tr><tr><td><code>actor</code> / <code>msg</code></td><td><code>String</code> (required)</td><td>Who spoke, and the line</td></tr><tr><td><code>detail</code></td><td><code>String</code></td><td>Full tool call/output for the expandable row</td></tr><tr><td><code>channel</code></td><td><code>String</code> (indexed)</td><td><code>main</code> or <code>run</code>; legacy rows without it count as main</td></tr><tr><td><code>conversationId</code></td><td><code>String</code> (indexed)</td><td>Which main chat this belongs to</td></tr><tr><td><code>byUser</code></td><td><code>String</code></td><td>The member who sent an <code>OPERATOR</code> line</td></tr><tr><td><code>attachments</code></td><td><code>[{ kind, file, alt }]</code></td><td>Files attached to a main-chat message</td></tr><tr><td><code>stats</code></td><td>subdocument</td><td><code>inputTokens</code>, <code>outputTokens</code>, <code>cacheReadTokens</code>, <code>cacheCreationTokens</code>, <code>ms</code>, <code>contextTokens</code>, <code>costUsd</code>, <code>costShared</code>, <code>model</code></td></tr><tr><td><code>expireAt</code></td><td><code>Date</code> (defaults to insert time)</td><td>TTL anchor — Mongo drops the row 90 days later</td></tr></tbody></table><p>Three indexes back it: <code>{ orgId: 1, t: -1 }</code> for the startup window, <code>{ orgId: 1, conversationId: 1, t: -1 }</code> for opening one chat, and a plain text index on <code>msg</code> + <code>detail</code> for recall. The text index is deliberately not compound with <code>orgId</code>, because local rows carry no <code>orgId</code> at all and a prefixed index would exclude them.</p><h3 id="chatconversation" tabindex="-1"><code>ChatConversation</code> <a class="header-anchor" href="#chatconversation" aria-label="Permalink to &quot;`ChatConversation`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>_id</code></td><td><code>String</code> (required)</td><td><code>&lt;orgId&gt;::&lt;id&gt;</code> — a chat id such as <code>main</code> is shared across orgs</td></tr><tr><td><code>id</code></td><td><code>String</code> (required, indexed)</td><td>The chat&#39;s own id, the one the app uses</td></tr><tr><td><code>orgId</code></td><td><code>String</code> (indexed)</td><td>Owning org</td></tr><tr><td><code>createdBy</code> / <code>sharedWith</code></td><td><code>String</code> / <code>[String]</code></td><td>Creator and invited viewers</td></tr><tr><td><code>title</code></td><td><code>String</code> (required)</td><td>Conversation title</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td><code>Number</code> (required)</td><td>Epoch ms</td></tr><tr><td><code>preview</code></td><td><code>String</code></td><td>Last-line preview for the list view</td></tr><tr><td><code>sessionId</code></td><td><code>String</code></td><td>Durable SDK session so PRIME resumes across restarts</td></tr><tr><td><code>pending</code></td><td>array</td><td>Queued/running inbound messages: <code>id</code>, <code>text</code>, <code>voice</code>, <code>attachments</code>, <code>userId</code>, <code>source</code> (<code>dashboard</code> | <code>telegram</code>), <code>channelChatId</code>, <code>enqueuedAt</code>, <code>state</code> (<code>queued</code> | <code>running</code>)</td></tr></tbody></table><h3 id="cron" tabindex="-1"><code>Cron</code> <a class="header-anchor" href="#cron" aria-label="Permalink to &quot;`Cron`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>_id</code></td><td><code>String</code> (required)</td><td>The cron&#39;s own id</td></tr><tr><td><code>orgId</code></td><td><code>String</code> (indexed) / <code>createdBy</code> <code>String</code></td><td>Owner; <code>createdBy</code>&#39;s budget and permissions govern each fire</td></tr><tr><td><code>name</code> / <code>schedule</code> / <code>brief</code></td><td><code>String</code> (required)</td><td>Label, cron expression, and the brief to run</td></tr><tr><td><code>project</code></td><td><code>String</code></td><td>Optional target project</td></tr><tr><td><code>enabled</code></td><td><code>Boolean</code> (required)</td><td>Whether the schedule is live</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td><code>Number</code> (required)</td><td>Epoch ms</td></tr><tr><td><code>nextFireAt</code> / <code>lastFiredAt</code> / <code>lastRunId</code></td><td><code>Number</code> / <code>String</code></td><td>Schedule bookkeeping and the run it produced</td></tr><tr><td><code>lastSkippedAt</code> / <code>lastSkipReason</code></td><td><code>Number</code> / <code>String</code></td><td>Why the most recent fire was skipped</td></tr></tbody></table><h3 id="reflex" tabindex="-1"><code>Reflex</code> <a class="header-anchor" href="#reflex" aria-label="Permalink to &quot;`Reflex`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>_id</code></td><td><code>String</code> (required)</td><td>The reflex&#39;s own id</td></tr><tr><td><code>orgId</code> (indexed) / <code>createdBy</code></td><td><code>String</code></td><td>Owner; <code>createdBy</code> governs each fire</td></tr><tr><td><code>name</code></td><td><code>String</code> (required)</td><td>Label</td></tr><tr><td><code>enabled</code></td><td><code>Boolean</code> (required)</td><td>Whether it listens</td></tr><tr><td><code>source</code> / <code>type</code></td><td><code>String</code> (required)</td><td>Event source and event type</td></tr><tr><td><code>match</code> / <code>action</code></td><td><code>Mixed</code> (required)</td><td>The structured trigger condition and what to do</td></tr><tr><td><code>brief</code> / <code>project</code></td><td><code>String</code></td><td>Brief and target project for the run it starts</td></tr><tr><td><code>cooldownSec</code> / <code>dedupKey</code> / <code>maxFires</code></td><td><code>Number</code> / <code>String</code> / <code>Number</code></td><td>Firing guards</td></tr><tr><td><code>requireApproval</code></td><td><code>Boolean</code></td><td>Park at an approval gate before acting</td></tr><tr><td><code>fireCount</code></td><td><code>Number</code></td><td>How many times it has fired</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td><code>Number</code> (required)</td><td>Epoch ms</td></tr><tr><td><code>lastFiredAt</code> / <code>lastRunId</code> / <code>lastSkippedAt</code> / <code>lastSkipReason</code> / <code>lastError</code></td><td></td><td>Most recent outcome</td></tr></tbody></table><h3 id="playbook" tabindex="-1"><code>Playbook</code> <a class="header-anchor" href="#playbook" aria-label="Permalink to &quot;`Playbook`&quot;">​</a></h3><p>A saved, frozen plan replayed by later runs.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>_id</code></td><td><code>String</code> (required)</td><td>The playbook&#39;s own id</td></tr><tr><td><code>orgId</code> (indexed) / <code>createdBy</code></td><td><code>String</code></td><td>Owner</td></tr><tr><td><code>name</code></td><td><code>String</code> (required)</td><td>Label</td></tr><tr><td><code>brief</code> / <code>project</code></td><td><code>String</code></td><td>The brief it was derived from, and its project</td></tr><tr><td><code>tasks</code></td><td><code>[Mixed]</code> (default <code>[]</code>)</td><td>The frozen task list</td></tr><tr><td><code>sourceRunId</code></td><td><code>String</code></td><td>The run it was captured from</td></tr><tr><td><code>memorySnapshot</code></td><td><code>[Mixed]</code></td><td>Memory applied when the plan was frozen</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td><code>Number</code> (required)</td><td>Epoch ms</td></tr><tr><td><code>useCount</code> / <code>lastUsedAt</code></td><td><code>Number</code></td><td>Replay counters</td></tr></tbody></table><h3 id="memory" tabindex="-1"><code>Memory</code> <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;`Memory`&quot;">​</a></h3><p>One document per markdown memory file. Mongo is authoritative; the files on disk are a materialized working copy.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>_id</code></td><td><code>String</code> (required)</td><td><code>&lt;orgId&gt;:&lt;rel&gt;</code></td></tr><tr><td><code>orgId</code></td><td><code>String</code> (required, indexed)</td><td>Owning org</td></tr><tr><td><code>rel</code></td><td><code>String</code> (required)</td><td>Forward-slash path under the org memory dir, e.g. <code>projects/foo.md</code></td></tr><tr><td><code>content</code></td><td><code>String</code> (required)</td><td>The file&#39;s full text</td></tr><tr><td><code>updatedAt</code></td><td><code>Number</code> (required)</td><td>Epoch ms</td></tr></tbody></table><h3 id="agentdef" tabindex="-1"><code>AgentDef</code> <a class="header-anchor" href="#agentdef" aria-label="Permalink to &quot;`AgentDef`&quot;">​</a></h3><p>One document per custom agent directory tree, per org.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>_id</code></td><td><code>String</code> (required)</td><td><code>&lt;orgId&gt;::&lt;name&gt;</code></td></tr><tr><td><code>orgId</code></td><td><code>String</code> (indexed)</td><td>Owning workspace</td></tr><tr><td><code>name</code></td><td><code>String</code> (required, indexed)</td><td>The agent&#39;s own name</td></tr><tr><td><code>files</code></td><td><code>[{ rel, b64 }]</code> (default <code>[]</code>)</td><td>Every packed file: forward-slash path under the agent dir, plus its bytes base64-encoded</td></tr><tr><td><code>skipped</code></td><td><code>[String]</code> (default <code>[]</code>)</td><td>Paths left out of <code>files</code> because packing them would exceed MongoDB&#39;s 16 MB document limit — they exist on disk only and the materializer preserves them</td></tr><tr><td><code>updatedAt</code></td><td><code>Number</code> (required)</td><td>Newest mtime in the tree</td></tr></tbody></table><p>Packing bounds the payload at 12 MB and takes files smallest-first, so <code>AGENT.md</code>, <code>.claude-plugin/plugin.json</code>, <code>skills/*/SKILL.md</code> and <code>mcp.json</code> always fit. <code>mcp-auth/</code> (per-server OAuth tokens), <code>workspace/</code> and any <code>node_modules</code> are never packed and never leave disk.</p><h3 id="identity-and-tenancy" tabindex="-1">Identity and tenancy <a class="header-anchor" href="#identity-and-tenancy" aria-label="Permalink to &quot;Identity and tenancy&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>Key fields</th></tr></thead><tbody><tr><td><code>User</code></td><td><code>_id</code>, <code>email</code> (unique), <code>name</code>, <code>passwordHash</code>, <code>emailVerifiedAt</code>, <code>avatarUrl</code>, <code>platformRole</code> (default <code>user</code>), <code>status</code> (default <code>active</code>), <code>createdAt</code>, <code>lastSeenAt</code></td></tr><tr><td><code>Identity</code></td><td><code>_id</code>, <code>userId</code> (indexed), <code>provider</code>, <code>issuer</code>, <code>subject</code>, <code>email</code>, <code>createdAt</code>; unique on <code>{ provider, issuer, subject }</code></td></tr><tr><td><code>Session</code></td><td><code>_id</code>, <code>tokenHash</code> (unique), <code>userId</code> (indexed), <code>createdAt</code>, <code>lastUsedAt</code>, <code>expiresAt</code> (indexed), <code>absoluteExpiresAt</code>, <code>ip</code>, <code>userAgent</code></td></tr><tr><td><code>AuthToken</code></td><td><code>_id</code>, <code>tokenHash</code> (unique), <code>purpose</code>, <code>userId</code> (indexed), <code>createdAt</code>, <code>expiresAt</code>, <code>usedAt</code></td></tr><tr><td><code>Organization</code></td><td><code>_id</code>, <code>name</code>, <code>slug</code> (unique), <code>seats</code> (default 1), <code>status</code>, <code>createdBy</code>, <code>createdAt</code>, <code>updatedAt</code>, <code>webhookKey</code> (unique), <code>limits</code>, <code>settings</code>, <code>billing</code></td></tr><tr><td><code>Membership</code></td><td><code>_id</code>, <code>orgId</code>, <code>userId</code> (indexed), <code>role</code>, <code>limits</code>, <code>permissionOverrides</code>, <code>agentAccess</code>, <code>createdAt</code>, <code>updatedAt</code>, <code>invitedBy</code>; unique on <code>{ orgId, userId }</code></td></tr><tr><td><code>Invite</code></td><td><code>_id</code>, <code>orgId</code> (indexed), <code>email</code>, <code>role</code>, <code>tokenHash</code> (unique), <code>invitedBy</code>, <code>createdAt</code>, <code>expiresAt</code>, <code>acceptedAt</code>, <code>limits</code>, <code>permissionOverrides</code></td></tr><tr><td><code>MemberUsagePeriod</code></td><td><code>orgId</code>, <code>userId</code>, <code>period</code>, <code>creditsSpent</code>, <code>runsStarted</code>, <code>updatedAt</code>; unique on <code>{ orgId, userId, period }</code></td></tr></tbody></table><h3 id="credits" tabindex="-1">Credits <a class="header-anchor" href="#credits" aria-label="Permalink to &quot;Credits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>Key fields</th></tr></thead><tbody><tr><td><code>CreditWallet</code></td><td><code>_id</code> (owner key, <code>default</code> in v0), <code>balance</code>, <code>currency</code>, <code>updatedAt</code></td></tr><tr><td><code>CreditLedger</code></td><td><code>_id</code> (entry id), <code>orgId</code> (indexed), <code>userId</code>, <code>at</code> (indexed), <code>delta</code>, <code>reason</code>, <code>runId</code>, <code>actor</code>, <code>rawCostUsd</code> (the platform&#39;s raw provider cost pre-margin), <code>models</code> (<code>[String]</code>), <code>balanceAfter</code>; compound index <code>{ orgId: 1, at: -1 }</code></td></tr></tbody></table><p><code>delta</code> can be smaller than <code>rawCostUsd</code> when the wallet floor truncates the final funded debit.</p><h3 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th>Key fields</th></tr></thead><tbody><tr><td><code>ChannelConfig</code></td><td><code>_id</code> = <code>&lt;orgId&gt;::&lt;channel&gt;</code>, <code>orgId</code> (required, indexed), <code>channel</code>, <code>enabled</code> (default <code>false</code>), <code>secrets</code> (<code>Mixed</code> — an encrypted blob), <code>publicCfg</code> (<code>Mixed</code>), <code>webhookSecret</code>; <code>timestamps: true</code></td></tr><tr><td><code>ChannelIdentity</code></td><td><code>_id</code> = <code>&lt;orgId&gt;::&lt;channel&gt;::&lt;externalId&gt;</code>, <code>orgId</code> (required, indexed), <code>channel</code>, <code>externalId</code>, <code>userId</code> (<code>&#39;&#39;</code> until <code>/link</code> completes), <code>displayName</code>, <code>firstSeen</code>, <code>lastSeen</code>, <code>messages</code>, <code>metadata</code></td></tr></tbody></table><h3 id="singleton-and-utility-documents" tabindex="-1">Singleton and utility documents <a class="header-anchor" href="#singleton-and-utility-documents" aria-label="Permalink to &quot;Singleton and utility documents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Model</th><th><code>_id</code></th><th>Payload</th></tr></thead><tbody><tr><td><code>SystemSettings</code></td><td><code>system</code></td><td><code>data</code> — the sanitized <code>SystemSettings</code> blob (replaces <code>config/settings.json</code>)</td></tr><tr><td><code>Secrets</code></td><td><code>system</code></td><td><code>blob</code> — the <code>Secrets</code> object, envelope-encrypted (AES-256-GCM, master-key-wrapped) in cloud, plain when no <code>SAIDI_MASTER_KEY</code> is set locally</td></tr><tr><td><code>ProviderProfiles</code></td><td><code>provider-profiles</code></td><td><code>data</code> — the sanitized <code>StoredProfile[]</code></td></tr><tr><td><code>ScanRoots</code></td><td><code>scan-roots</code></td><td><code>data</code> — <code>{ roots: string[] }</code>, the directories scanned for git repos</td></tr><tr><td><code>RuntimeState</code></td><td>caller-chosen</td><td><code>data</code>, <code>updatedAt</code> — small runtime blobs that do not warrant their own schema</td></tr><tr><td><code>Migration</code></td><td>caller-chosen</td><td><code>version</code>, <code>completedAt</code>, <code>source</code>, <code>manifest</code> — durable markers for one-time destructive migrations</td></tr></tbody></table><h2 id="how-runs-are-persisted" tabindex="-1">How runs are persisted <a class="header-anchor" href="#how-runs-are-persisted" aria-label="Permalink to &quot;How runs are persisted&quot;">​</a></h2><p><code>RunStore</code> holds the in-memory working copy and delegates durability to a <code>RunPersistence</code> adapter. <code>MongoRunPersistence</code> is production; <code>FileRunPersistence</code> (<code>&lt;runsRoot&gt;/&lt;id&gt;/run.json</code>) is a unit-test adapter.</p><p>Writes come in two flavours. <code>persist()</code> is immediate and used for creation and every lifecycle or participant change, so a crash never loses a critical transition. <code>persistSoon()</code> coalesces the hot append path on a 750 ms debounce; an immediate write cancels any pending debounced flush because it is a superset of it.</p><p>Inside the Mongo adapter, <code>persist()</code> picks one of two paths:</p><ul><li><strong>Delta (append-only fast path).</strong> Taken when a per-run high-water mark exists, <code>thread</code> and <code>usageLog</code> only grew, and the previously written prefix is intact (checked by comparing the id of the last written event). It <code>$push</code>es only the new tail, <code>$set</code>s the small scalar fields, and <code>$unset</code>s the cleared optional keys listed in <code>CLEARABLE_RUN_KEYS</code> so a removed <code>pendingApproval</code> or <code>attention</code> actually disappears.</li><li><strong>Full <code>replaceOne</code>.</strong> Taken on the first write of a run in the process, or when the thread was rewound so the prefix no longer matches.</li></ul><p>Two more details matter:</p><ul><li><code>patchEvents()</code> rewrites thread events edited in place, addressed by index. The delta path treats <code>thread</code> as append-only, so stamping a settled turn&#39;s cost back onto earlier messages is invisible to it. Only positions below the high-water mark are patched — <code>$set</code>ting past the stored array&#39;s length would pad it with nulls.</li><li>Writes for one run are serialized through a per-id promise chain, because every write carries the full scalar set including <code>status</code>; two overlapping fire-and-forget writes could otherwise land out of order and revert a settled run to <code>active</code>. Different runs still write concurrently. <code>flush()</code> drains the chains (up to five passes) so shutdown completes before the connection drops.</li></ul><p>Any failed write drops the high-water mark, which makes the next write a full <code>replaceOne</code> that self-heals.</p><h2 id="how-runs-are-reloaded" tabindex="-1">How runs are reloaded <a class="header-anchor" href="#how-runs-are-reloaded" aria-label="Permalink to &quot;How runs are reloaded&quot;">​</a></h2><p><code>RunStore.init()</code> loads durable records once at startup via <code>loadAsync()</code>. Each record goes through <code>mergeLoaded()</code>:</p><ul><li>An older durable copy never replaces a newer in-memory one (<code>updatedAt</code> wins).</li><li>A run left <code>active</code> or <code>awaiting_input</code> when the process stopped is downgraded to <code>paused</code>; the engine never auto-resumes. A <code>SYSTEM</code> thread event is appended naming each killed in-flight delegation (up to five), so the interruption is visible and PRIME&#39;s live-state block knows what died.</li><li>A resting run that still carries <code>inFlight</code>/<code>inFlights</code> has them cleared.</li></ul><p><code>RunStore.reload()</code> is the out-of-band resync. It fetches the newest 500 runs by <code>updatedAt</code> (<code>RELOAD_LIMIT</code>) so a large org never pulls every full run document. Because the fetch is bounded, &quot;absent from the list&quot; no longer means &quot;deleted&quot;: an in-memory run is only evicted if it is absent <strong>and</strong> its <code>updatedAt</code> is at or above the oldest fetched run. With <code>protectActive</code>, live runs are left alone — their newest streamed events may not be persisted yet. A durable copy older than the in-memory one is never applied.</p><p>See <a href="/docs/concepts/runs">Runs</a> for the lifecycle these rules protect.</p><h2 id="where-files-live" tabindex="-1">Where files live <a class="header-anchor" href="#where-files-live" aria-label="Permalink to &quot;Where files live&quot;">​</a></h2><p>Alongside Mongo, each workspace has a file tree that agents actually read and write. It is nested one level per workspace, and no user-supplied id is ever joined into a path, so nothing can escape its own workspace root.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>orgs/&lt;orgId&gt;/</span></span>\n<span class="line"><span>├── memory/</span></span>\n<span class="line"><span>│   ├── members/&lt;userId&gt;/global.md      # per-member personal memory</span></span>\n<span class="line"><span>│   ├── members/&lt;userId&gt;/learning.json</span></span>\n<span class="line"><span>│   ├── learning.json                   # structured learned memory sidecar</span></span>\n<span class="line"><span>│   ├── projects/&lt;name&gt;.md              # per-project memory, shared across the workspace</span></span>\n<span class="line"><span>│   ├── agents/&lt;name&gt;.md                # per-agent memory, shared across the workspace</span></span>\n<span class="line"><span>│   ├── chat/log.json                   # main-chat agent call log</span></span>\n<span class="line"><span>│   ├── chat-uploads/                   # files attached to main-chat messages</span></span>\n<span class="line"><span>│   ├── activity-log.json               # activity window fallback when Mongo is down</span></span>\n<span class="line"><span>│   ├── activity-unsynced.jsonl         # journal of activity not yet in Mongo</span></span>\n<span class="line"><span>│   └── runs/&lt;runId&gt;/                   # see below</span></span>\n<span class="line"><span>├── agents/                             # custom agent definition dirs</span></span>\n<span class="line"><span>│   └── &lt;name&gt;/AGENT.md, skills/&lt;slug&gt;/SKILL.md, mcp.json,</span></span>\n<span class="line"><span>│       .claude-plugin/plugin.json, mcp-auth/, workspace/</span></span>\n<span class="line"><span>├── config/</span></span>\n<span class="line"><span>└── repos/                              # per-workspace repo checkouts</span></span></code></pre></div><p>Each run owns a directory under the org&#39;s <code>runs/</code> root :</p><table tabindex="0"><thead><tr><th>Path helper</th><th>Directory</th><th>Purpose</th></tr></thead><tbody><tr><td><code>runDir(id)</code></td><td><code>runs/&lt;id&gt;</code></td><td>The run&#39;s whole on-disk folder</td></tr><tr><td><code>runAssetsDir(id)</code></td><td><code>runs/&lt;id&gt;/assets</code></td><td>Images and deliverables served via <code>/api/run-asset</code></td></tr><tr><td><code>runWorkRoot(id)</code></td><td><code>runs/&lt;id&gt;/work</code></td><td>Mounted as <code>/workspace</code> in the run&#39;s sandbox</td></tr><tr><td><code>runWorkDir(id, agent)</code></td><td><code>runs/&lt;id&gt;/work/&lt;agent&gt;</code></td><td>One agent&#39;s per-run workspace</td></tr><tr><td><code>runRepoRoot(id)</code> / <code>runRepoDir(id, project)</code></td><td><code>runs/&lt;id&gt;/repos[/&lt;project&gt;]</code></td><td>Private git worktrees, kept outside the repo so they never show up as untracked files in a diff</td></tr><tr><td><code>runOutputDir(id)</code></td><td><code>runs/&lt;id&gt;/output</code></td><td>Sandbox drop zone (<code>/run/output</code>), swept into <code>assets</code> after each delegation</td></tr><tr><td><code>runSharedDir(id)</code></td><td><code>runs/&lt;id&gt;/shared</code></td><td>Cross-agent handoff notes (<code>/run/shared</code>)</td></tr><tr><td><code>runConfigRoot(id)</code></td><td><code>runs/&lt;id&gt;/agent-config</code></td><td>Per-run SDK config/session store, so resume transcripts survive across delegations</td></tr><tr><td>—</td><td><code>runs/&lt;id&gt;/log.json</code></td><td>The run&#39;s agent call log</td></tr></tbody></table><p><code>promoteRunAssets()</code> copies (never moves) generated files from the run-level <code>output/</code> drop zone and each agent workspace&#39;s <code>assets/</code> and <code>output/</code> subdirectories into the served assets dir, skipping names that already exist and ignoring <code>up-</code> prefixed uploads. Files must match <code>^[\\w.-]+$</code> to be listed.</p><p>Deleting a run removes the Mongo document and, unless you keep files, the whole <code>runs/&lt;id&gt;/</code> directory — the record and the artifacts are separate deletions because assets live on disk in every mode.</p><h2 id="materialized-working-copies" tabindex="-1">Materialized working copies <a class="header-anchor" href="#materialized-working-copies" aria-label="Permalink to &quot;Materialized working copies&quot;">​</a></h2><p>Two things exist in both places, with Mongo authoritative:</p><ul><li><strong>Memory.</strong> <code>initOrgMemory(orgId)</code> runs on org hydration: it deletes on-disk files whose documents are gone, then writes every document&#39;s <code>content</code> to its <code>rel</code> path. <code>persistMemory(rel, content)</code> and <code>syncMemoryFileToMongo(full)</code> write changes back. All writes are best-effort and fire-and-forget — memory must never break a turn — and no-op when Mongo is down. Only the enumerated paths are synced (<code>global.md</code>, <code>learning.json</code>, <code>members/&lt;id&gt;/*</code>, <code>projects/*.md</code>, <code>agents/*.md</code>), so a generated file such as <code>INDEX.md</code> at the memory root is never touched.</li><li><strong>Agent definitions.</strong> <code>initAgents()</code> re-materializes an org&#39;s agent directories from Mongo on first access, and every mutation mirrors back. Stored <code>rel</code> paths are validated against the agent root and the agent name against <code>^[a-z0-9][a-z0-9-]{1,40}$</code> so a poisoned document cannot write outside the org&#39;s agents dir.</li></ul><p>Legacy per-store JSON files (<code>crons.json</code>, <code>chats.json</code>, <code>reflexes.json</code>, <code>playbooks.json</code>, <code>credits.json</code>, <code>credit-ledger.jsonl</code>, <code>secrets.json</code>) are migration input only. In production every store is constructed with <code>loadLegacyFile: false</code>, so it neither reads nor rewrites them.</p><p>More context: <a href="/docs/concepts/memory">Memory</a> · <a href="/docs/concepts/tenancy-and-identity">Tenancy, Identity &amp; Access</a></p>',68)])])}const g=d(r,[["render",a]]);export{p as __pageData,g as default};
